type plannedLine struct {
	start, end int // byte range of the line content in data, excluding the line ending
	nlLen      int // length of the line ending: 0 (EOF, none), 1 (LF or bare CR), or 2 (CRLF)
	kind       int
	opener     bool   // structured line that opens a heredoc at its end
	marker     []byte // marker bytes, for opener lines
}

// planFormat scans data and builds the line plan. It returns ok=false
// when the input is malformed in a way that Format must leave
// untouched: unterminated quote, dangling escape, mismatched braces,
// or an unterminated heredoc. The scan is read-only.
func planFormat(data []byte) (lines []plannedLine, ok bool) {
	var (
		quotes string // quote state carried across physical lines: "", `"`, "`", "`\"", "\"`"

		braceDepth int
		minDepth   int

		heredocMarker []byte // marker of the currently open heredoc, if any
	)

	orphanEscape := false

	for pos := 0; pos < len(data); {
		start := pos
		for pos < len(data) && data[pos] != '\n' && data[pos] != '\r' {
			pos++
		}
		end := pos
		nlLen := 0
		if pos < len(data) {
			if data[pos] == '\r' && pos+1 < len(data) && data[pos+1] == '\n' {
				nlLen = 2
			} else {
				nlLen = 1
			}
			pos += nlLen
		}

		if heredocMarker != nil {
			// A closing marker is the marker alone on a line boundary,
			// preceded only by spaces or tabs; anything else is body.
			content := data[start:end]
			trimmed := bytes.TrimLeft(content, " \t")
			line := plannedLine{start: start, end: end, nlLen: nlLen}
			if bytes.Equal(trimmed, heredocMarker) {
				line.kind = lineHeredocClose
				heredocMarker = nil
			} else {
				line.kind = lineHeredocBody
			}
			lines = append(lines, line)
			continue
		}

		line := plannedLine{start: start, end: end, nlLen: nlLen, kind: lineStructured}

		// Lexical scan of the structured line content.
		var (
			escaped      bool
			comment      bool
			atTokenStart = true
		)
		i := start
		for i < end {
			r, size := utf8.DecodeRune(data[i:end])

			if comment {
				i += size
				continue
			}

			if quotes != "" {
				if !escaped && r == '\\' {
					escaped = true
					i += size
					continue
				}
				if escaped {
					escaped = false
					i += size
					continue
				}
				switch r {
				case '`':
					switch quotes {
					case "\"`":
						quotes = "\""
					case "`":
						quotes = ""
					case "\"":
						quotes = "\"`"
					}
				case '"':
					switch quotes {
					case "\"":
						quotes = ""
					case "`\"":
						quotes = "`"
					case "\"`":
						quotes = ""
					}
				}
				i += size
				continue
			}

			if !escaped && r == '\\' {
				escaped = true
				atTokenStart = false
				i += size
				continue
			}
			if escaped {
				escaped = false
				atTokenStart = false
				i += size
				continue
			}

			switch {
			case r == '`':
				quotes = "`"
				atTokenStart = false
			case r == '"' && atTokenStart:
				quotes = "\""
				atTokenStart = false
			case r == '#':
				comment = true
			case r == '{':
				braceDepth++
				atTokenStart = false
			case r == '}':
				braceDepth--
				if braceDepth < minDepth {
					minDepth = braceDepth
				}
				atTokenStart = false
			case r == '<' && atTokenStart && i+1 < end && data[i+1] == '<':
				// Potential heredoc opener: "<<" starts a token; the
				// marker runs until whitespace or the line ending.
				mStart := i + 2
				mEnd := mStart
				for mEnd < end {
					mr, mSize := utf8.DecodeRune(data[mEnd:end])
					if mr != bomRune && unicode.IsSpace(mr) {
						break
					}
					mEnd += mSize
				}
				// The opener is only recognized at a line ending, with
				// a non-empty valid marker and no third '<'.
				if mEnd == end && nlLen > 0 {
					marker := data[mStart:mEnd]
					if len(marker) > 0 && marker[0] != '<' && heredocMarkerRegexp.Match(marker) {
						line.opener = true
						heredocMarker = bytes.Clone(marker)
					}
				}
				i = mEnd
				atTokenStart = false
				continue
			default:
				if r != bomRune && unicode.IsSpace(r) {
					atTokenStart = true
				} else {
					atTokenStart = false
				}
			}
			i += size
		}

		// A backslash with nothing after it before EOF is a dangling escape.
		if quotes == "" && escaped && nlLen == 0 {
			orphanEscape = true
		}

		lines = append(lines, line)
	}

	ok = quotes == "" && heredocMarker == nil &&
		braceDepth == 0 && minDepth >= 0 && !orphanEscape
	return lines, ok
}

// formatBytes runs the formatting state machine over data according to
// the plan. The returned slice is freshly allocated and aliases
// nothing. ok=false means the plan rejected the input.
func formatBytes(data []byte, emitBOM bool) (result []byte, ok bool) {
	lines, planOK := planFormat(data)
	if !planOK {
		return nil, false
	}

	w := &fmtState{
		out:              new(bytes.Buffer),
		space:            true,
		beginningOfLine:  true,
	}
	if emitBOM {
		w.out.Write(bomBytes)
	}

	for _, line := range lines {
		switch line.kind {
		case lineHeredocBody:
			// Body lines are copied byte for byte: spaces, tabs,
			// carriage returns, braces, and comments are untouched.
			w.out.Write(data[line.start : line.end+line.nlLen])
			continue

		case lineHeredocClose:
			// The closing marker keeps its correspondence with the
			// opening one, but its leading indentation is normalized
			// like any structured line.
			w.indent()
			w.out.Write(w.heredocMarker)
			w.nextLine()
			w.space = true
			w.heredocMarker = nil
			continue
		}

		// Structured line: run the character state machine over the
		// content, then feed a single normalized line ending.
		for p := line.start; p < line.end; {
			r, size := utf8.DecodeRune(data[p:line.end])
			w.emit(r, data[p:p+size])
			p += size
		}

		if line.nlLen == 0 {
			continue
		}

		if w.quotes != "" {
			// Inside a quote, line ending bytes (including any CR) are
			// preserved exactly as they appeared in the input.
			term := data[line.end : line.end+line.nlLen]
			w.out.Write(term)
			w.last = rune(term[len(term)-1])
			w.escaped = false
			continue
		}

		// CRLF, bare CR, and LF in structured parts all become LF.
		w.emit('\n', nil)

		if line.opener {
			// The heredoc body starts immediately after this newline,
			// so the (otherwise deferred) line break is written now
			// and the structural state is frozen for the body lines.
			for i := 0; i < w.newLines; i++ {
				w.nextLine()
			}
			w.newLines = 0
			w.space = true
			w.heredocMarker = line.marker
		}
	}

	// The Caddyfile does not need leading or trailing spaces, but...
	trimmed := trimSpaceKeepBOM(w.out.Bytes())

	// ...Caddyfiles should, however, end with a newline because
	// newlines are significant to the syntax of the file.
	out := make([]byte, 0, len(trimmed)+1)
	out = append(out, trimmed...)
	out = append(out, '\n')

	return out, true
}

// fmtState is the character-level formatting state machine. It is a
// direct continuation of the historical stream formatter: whitespace
// and brace placement are rewritten, while quoted, commented, escaped,
// and plain token bytes pass through literally.
type fmtState struct {
	out *bytes.Buffer

	last rune // the last character that was written to the result

	space           bool // whether current/previous character was whitespace (beginning of input counts as space)
	beginningOfLine bool // whether we are at beginning of line

	openBrace        bool // whether current word/token is or started with open curly brace
	openBraceWritten bool // if openBrace, whether that brace was written or not
	openBraceSpace   bool // whether there was a non-newline space before open brace

	newLines int // count of newlines consumed

	comment bool   // whether we're in a comment
	quotes  string // encountered quotes ('', '`', '"', '"`', '`"')
	escaped bool   // whether current char is escaped

	heredocEscaped bool   // whether a heredoc opener is escaped
	heredocMarker  []byte // marker of the heredoc whose body is being copied

	nesting int // indentation level

	currentToken                  strings.Builder
	currentLineFirstToken         string
	previousLineWasTopLevelImport bool
	openBraceOwnLine              bool
}

func (w *fmtState) finishToken() {
	if w.currentToken.Len() == 0 {
		return
	}
	if w.currentLineFirstToken == "" {
		w.currentLineFirstToken = w.currentToken.String()
	}
	w.currentToken.Reset()
}

func (w *fmtState) finishLine() {
	w.finishToken()
	if w.currentLineFirstToken != "" {
		w.previousLineWasTopLevelImport = w.nesting == 0 && w.currentLineFirstToken == "import"
	} else if !w.openBrace || !w.openBraceOwnLine || w.openBraceWritten {
		w.previousLineWasTopLevelImport = false
	}
	w.currentLineFirstToken = ""
}

// writeSynth writes a character produced by the formatter itself.
func (w *fmtState) writeSynth(ch rune) {
	w.out.WriteRune(ch)
	w.last = ch
}

// writeInput writes a character that came from the input: literal byte
// spans are copied untouched so that invalid UTF-8 and multi-byte
// sequences keep their original byte boundaries.
func (w *fmtState) writeInput(ch rune, lit []byte) {
	if lit != nil {
		w.out.Write(lit)
	} else {
		w.out.WriteRune(ch)
	}
	w.last = ch
}

func (w *fmtState) indent() {
	for tabs := w.nesting; tabs > 0; tabs-- {
		w.writeSynth('\t')
	}
}

func (w *fmtState) nextLine() {
	w.writeSynth('\n')
	w.beginningOfLine = true
}

// emit feeds one decoded character to the formatting state machine.
// lit is the original byte span of the character in the input; it is
// nil for synthesized characters (such as the normalized line feed).
func (w *fmtState) emit(ch rune, lit []byte) {
	if w.last == '<' && w.space {
		w.space = false
	}

	if w.comment {
		if ch == '\n' {
			w.comment = false
			w.space = true
			w.nextLine()
			return
		}
		w.writeInput(ch, lit)
		return
	}

	if !w.escaped && ch == '\\' {
		if w.space {
			w.writeSynth(' ')
			w.space = false
		}
		w.writeInput(ch, lit)
		w.escaped = true
		return
	}

	if w.escaped {
		if ch == '<' {
			w.heredocEscaped = true
		}
		w.writeInput(ch, lit)
		w.escaped = false
		return
	}

	if ch == '`' {
		switch w.quotes {
		case "\"`":
			w.quotes = "\""
		case "`":
			w.quotes = ""
		case "\"":
			w.quotes = "\"`"
		default:
			w.quotes = "`"
		}
	}

	if w.quotes == "\"" {
		if ch == '"' {
			w.quotes = ""
		}
		w.writeInput(ch, lit)
		return
	}

	if ch == '"' {
		switch w.quotes {
		case "":
			if w.space {
				w.quotes = "\""
			}
		case "`\"":
			w.quotes = "`"
		case "\"`":
			w.quotes = ""
		}
	}

	if strings.Contains(w.quotes, "`") {
		if ch == '`' && w.space && !w.beginningOfLine {
			w.writeSynth(' ')
		}
		w.writeInput(ch, lit)
		w.space = false
		return
	}

	// A BOM anywhere outside of the leading file-marker position is an
	// ordinary content character: it is never folded as whitespace.
	if unicode.IsSpace(ch) && ch != bomRune {
		w.finishToken()
		w.space = true
		w.heredocEscaped = false
		if ch == '\n' {
			w.finishLine()
			w.newLines++
		}
		return
	}
	spacePrior := w.space
	w.space = false

	//////////////////////////////////////////////////////////
	// I find it helpful to think of the formatting loop in two
	// main sections; by the time we reach this point, we
	// know we are in a "regular" part of the file: we know
	// the character is not a space, not in a literal segment
	// like a comment or quoted, it's not escaped, etc.
	//////////////////////////////////////////////////////////

	if ch == '#' {
		w.comment = true
	}

	if w.openBrace && spacePrior && !w.openBraceWritten {
		if w.nesting == 0 && w.last == '}' {
			w.nextLine()
			w.nextLine()
		}

		w.openBrace = false
		if w.openBraceOwnLine && w.previousLineWasTopLevelImport {
			if w.last != '\n' {
				w.nextLine()
			}
			w.indent()
		} else if w.beginningOfLine {
			w.indent()
		} else if !w.openBraceSpace || !unicode.IsSpace(w.last) {
			w.writeSynth(' ')
		}
		w.writeSynth('{')
		w.openBraceWritten = true
		w.openBraceOwnLine = false
		w.nextLine()
		w.newLines = 0
		// prevent infinite nesting from ridiculous inputs (issue #4169)
		if w.nesting < 10 {
			w.nesting++
		}
	}

	switch {
	case ch == '{':
		w.finishToken()
		w.openBrace = true
		w.openBraceSpace = spacePrior && !w.beginningOfLine
		w.openBraceOwnLine = w.newLines > 0
		if w.openBraceSpace && w.newLines == 0 {
			w.writeSynth(' ')
		}
		w.openBraceWritten = false
		if w.quotes == "`" {
			w.writeInput(ch, lit)
			w.openBraceWritten = true
			w.openBraceOwnLine = false
			return
		}
		return

	case ch == '}' && (spacePrior || !w.openBrace):
		w.finishToken()
		if w.quotes == "`" {
			w.writeInput(ch, lit)
			return
		}
		if w.last != '\n' {
			w.nextLine()
		}
		if w.nesting > 0 {
			w.nesting--
		}
		w.indent()
		w.writeSynth('}')
		w.newLines = 0
		return
	}

	if w.newLines > 2 {
		w.newLines = 2
	}
	for i := 0; i < w.newLines; i++ {
		w.nextLine()
	}
	w.newLines = 0
	if w.beginningOfLine {
		w.indent()
	}
	if w.nesting == 0 && w.last == '}' && w.beginningOfLine {
		w.nextLine()
		w.nextLine()
	}

	if !w.beginningOfLine && spacePrior {
		w.writeSynth(' ')
	}

	if w.openBrace && !w.openBraceWritten {
		w.writeSynth('{')
		w.openBraceWritten = true
	}

	if spacePrior && ch == '<' {
		w.space = true
	}

	if ch != bomRune && ch != utf8.RuneError {
		w.currentToken.WriteRune(ch)
	}
	w.writeInput(ch, lit)

	w.beginningOfLine = false
}

