		default: // LF or bare CR
			w.emit(rune(data[line.end]), data[line.end:line.end+1])
		}

	default:
		// CRLF, bare CR, and LF in structured parts all become LF.
		w.emit('\n', nil)
	}

	if line.opener {
		// The heredoc body starts immediately after this newline,
		// so the (otherwise deferred) line break is written now and
		// the structural state is frozen for the body lines.
		if w.newLines > 2 {
			w.newLines = 2
		}
		for i := 0; i < w.newLines; i++ {
			w.nextLine()
		}
		w.newLines = 0
		w.space = true
	}
}

