func TestDbgDiffRandom(t *testing.T) {
	rng := rand.New(rand.NewSource(1))
	alphabet := []byte("ab{} \t\n#\"`\\<>/.*_-E12")
	diffs := 0
	for iter := 0; iter < 200000; iter++ {
		n := rng.Intn(30)
		in := make([]byte, n)
		for i := range in {
			in[i] = alphabet[rng.Intn(len(alphabet))]
